<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Search & Views · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'search-navigation',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><nav class="breadcrumbs"><a href="<?=esc(url_for())?>">Atlas</a><span>›</span><strong>Search & Views</strong></nav><header class="page-header"><div><p class="eyebrow">FIND AND RETURN</p><h1>Search, favorites, and recent pages</h1><p>Use <kbd>/</kbd> to focus search and <kbd>Esc</kbd> to clear it.</p></div></header><form method="get" class="global-search-page"><input type="hidden" name="route" value="search-navigation"><label>Search Atlas<input name="q" value="<?=esc($searchTerm)?>" placeholder="People, email, departments, positions, shifts" data-global-search autofocus></label><button class="button primary">Search</button></form><section class="planning-grid"><article class="panel span-2"><h2>Results</h2><?php foreach($searchResults as $result):$target=$result['route'].($result['type']==='person'?'?membership_id='.$result['id']:'');?><a class="planning-row" href="<?=esc(url_for($target))?>"><span><strong><?=esc($result['title'])?></strong><small><?=esc(ucfirst($result['type']).' · '.($result['subtitle']??''))?></small></span><b>›</b></a><?php endforeach;?><?php if($searchTerm&&!$searchResults):?><div class="inline-empty"><strong>No matching Atlas records</strong></div><?php endif;?></article><article class="panel"><h2>Favorites and saved views</h2><?php foreach($savedViews as $view):$query=http_build_query($view['parameters']);?><a class="planning-row" href="<?=esc(url_for($view['route'].($query?'?'.$query:'')))?>"><span><strong><?=$view['favorite']?'★ ':''?><?=esc($view['name'])?></strong><small><?=esc(ucfirst($view['view_type']))?></small></span></a><?php endforeach;?></article><article class="panel"><h2>Recent pages</h2><?php foreach($recentNavigation as $recent):?><a class="planning-row" href="<?=esc(url_for($recent['route']))?>"><span><strong><?=esc($recent['title'])?></strong><small><?=esc($recent['visited_at'])?></small></span></a><?php endforeach;?></article></section></main><script src="<?=esc(url_for('assets/app.js'))?>"></script></body></html>
